"""Managed Offices client review, scoped to the existing category page."""
import re
ARROW='<svg aria-hidden="true" focusable="false" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"><path d="M9 5l7 7-7 7"/></svg>'
DIALOG='''<dialog id="speak-dialog" aria-labelledby="speak-title"><div class="we-form-panel"><button type="button" class="modal-close" id="speak-close" aria-label="Close consultation form">×</button><p class="we-form-kicker">OFFICE CONSULTATION</p><h2 id="speak-title">Book a consultation</h2><p class="we-form-intro">Tell us what you need and our team will get in touch.</p><form id="speak-form" class="we-form we-form-modal"><div class="field-grid"><div class="field we-field"><label for="speak-name">Full name</label><input id="speak-name" name="fullName" required autocomplete="name" placeholder=" "></div><div class="field we-field"><label for="speak-phone">Phone number</label><input id="speak-phone" name="phone" required autocomplete="tel" type="tel" pattern="[0-9+\\s\\-\\(\\)]{8,20}" placeholder=" "></div><div class="field we-field"><label for="speak-email">Work email (optional)</label><input id="speak-email" name="email" autocomplete="email" type="email" placeholder=" "></div><div class="field we-field"><label for="speak-team">Team size</label><select id="speak-team" name="team" required><option value=""></option><option>1–10 people</option><option>11–50 people</option><option>51+ people</option></select></div></div><button type="submit">Request a callback</button><p class="form-status" id="speak-status" role="status">We use your details only to get back to you about this enquiry.</p></form></div></dialog>'''
SCRIPT='''(()=>{const d=document.getElementById('speak-dialog'),b=document.getElementById('open-speak'),f=document.getElementById('speak-form'),status=document.getElementById('speak-status');if(!d||!b||!f)return;b.addEventListener('click',()=>{d.showModal();document.getElementById('speak-name').focus()});document.getElementById('speak-close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>b.focus());f.addEventListener('submit',async e=>{e.preventDefault();if(!f.reportValidity())return;const data=new FormData(f),payload={source:'category-consultation',name:data.get('fullName'),phone:data.get('phone'),email:data.get('email'),teamSize:data.get('team')};const msg=['Hello Workspace by Emlen, I would like to speak with your office consultation team.','Name: '+payload.name,'Phone: '+payload.phone,'Work email: '+(payload.email||'Not provided'),'Team size: '+payload.teamSize].join('\\n');const submit=f.querySelector('button[type=submit]');submit.disabled=true;try{await EmlenLead.deliver(msg,payload,status)}catch(err){status.textContent='We could not send your request. Please try again or call +91 98149 53954.'}finally{submit.disabled=false}})})();'''
def patch_managed_review(body):
    body,n=re.subn(r'(<span\b[^>]*class="office-arrow"[^>]*>)↗(</span>)',lambda m:m[1]+ARROW+m[2],body)
    if n!=7:raise ValueError('office arrows '+str(n))
    body,n=re.subn(r'Looking for a different office<br\s*/?>solution\?', 'Looking for a <span class="other-highlight">different office solution</span>?',body,count=1)
    if n!=1:raise ValueError('more services heading')
    body,n=re.subn(r'<div class="consult-copy">\s*(<p class="consult-kicker">[\s\S]*?</p>)\s*<h2 id="consult-heading">[\s\S]*?</h2>',r'<div class="consult-copy"><div class="consult-heading-row">\1<h2 id="consult-heading">Talk to us before <em>you choose.</em></h2></div>',body,count=1)
    if n!=1:raise ValueError('consult heading')
    body,n=re.subn(r'<a class="consult-call" href="tel:[^"]+">[\s\S]*?</a>', '<button class="consult-call" type="button" id="open-speak" aria-haspopup="dialog">Book a consultation <span class="we-cta-chevron" aria-hidden="true">↗</span></button>',body,count=1)
    if n!=1:raise ValueError('consult CTA')
    # Keep original field identifiers and lead API contract. Full name is
    # assembled from the required first name and optional surname.
    body,n=re.subn(r'<label for="fullName">Full name</label>(<input\b[^>]*\bid="fullName"[^>]*>)</div>',lambda m:'<label for="fullName">First name</label>'+m[1].replace('autocomplete="name"','autocomplete="given-name"')+'</div><div class="field we-field"><label for="lastName">Last name (optional)</label><input autocomplete="family-name" id="lastName" name="lastName" placeholder=" " type="text"></div>',body,count=1)
    if n!=1:raise ValueError('first name field')
    body,n=re.subn(r'<div class="field full we-field">(?=<label for="interest">)', '<div class="field we-field">',body,count=1)
    if n!=1:raise ValueError('interest field')
    # Retain all choices and existing JS preselection values.
    body=body.replace("<label for=\"interest\">I'm interested in <span>(optional)</span></label>", '<label for="interest">Office preference (optional)</label>')
    full="f.elements.namedItem('fullName').value"
    if body.count(full)!=2:raise ValueError('enquiry name bindings')
    body=body.replace(full,"[f.elements.namedItem('fullName').value.trim(),f.elements.namedItem('lastName').value.trim()].filter(Boolean).join(' ')")
    body,n=re.subn(r'<span class="star">\s*★\s*</span>', '',body,count=1)
    # All action arrows, including the services, FAQ and benefit buttons;
    # not the select down-caret, check marks or decorative plus markers.
    body=re.sub(r'(<span\b[^>]*>)\s*↗\s*(</span>)',lambda m:m[1]+ARROW.replace('<svg ','<svg class="we-action-chevron" ',1)+m[2],body)
    body=body.replace('<span class="arr">','<span class="arr" aria-hidden="true">')
    dialog=DIALOG.replace('Request a callback</button>','Request a callback <span aria-hidden="true">'+ARROW.replace('<svg ','<svg class="we-action-chevron" ',1)+'</span></button>')
    # Measure actual fixed navigation height, including responsive styles.
    spacing="""(()=>{const copy=document.querySelector('#top.hero .copy'),nav=document.querySelector('.em-nav'),sub=copy?.querySelector('.eyebrow');if(!copy||!nav||!sub)return;let frame;const measure=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const gap=sub.getBoundingClientRect().top+window.scrollY-nav.getBoundingClientRect().bottom;const current=parseFloat(getComputedStyle(copy).marginTop)||0;if(Math.abs(gap-80)>.5)copy.style.setProperty('--managed-hero-top',(current+80-gap)+'px')})};measure();window.addEventListener('resize',measure,{passive:true});if('ResizeObserver'in window){const observer=new ResizeObserver(measure);observer.observe(nav)}document.fonts?.ready.then(measure)})();"""
    return body+'\n'+dialog+'\n<script>'+SCRIPT+'\n'+spacing+'</script>\n'
